/**
 * Navigation helpers for the POS flow.
 *
 * The app enables `experiments.typedRoutes`, and .expo/types/router.d.ts is
 * regenerated by Metro when `expo start` runs — so newly added routes are not
 * in the generated union until the dev server has booted once. These helpers
 * centralize the (safe, string-only) casts so screens stay clean and G1c can
 * reuse them for its add-product target route.
 */
import type { Href } from 'expo-router';

export function posHref(path: string): Href {
  return path as unknown as Href;
}

export function posHrefWithParams(path: string, params: Record<string, string>): Href {
  return { pathname: path, params } as unknown as Href;
}

/** Routes owned by G1b */
export const POS_ROUTES = {
  scan: '/pos',
  checkout: '/pos/checkout',
  receipt: (saleId: string) => `/pos/receipt/${saleId}`,
} as const;

/**
 * Route owned by G1c (scan-to-add-product). G1b navigates here with the
 * scanned code; G1c implements the screen at app/pos/add-product.tsx.
 */
export const ADD_PRODUCT_ROUTE = '/pos/add-product';
